def write_hdr(filename,pixels):
 height,width=pixels.shape[:2];data=np.maximum(pixels[::-1],0);peak=data.max(axis=2);mant,exponent=np.frexp(peak);scale=np.divide(mant*256,peak,out=np.zeros_like(peak),where=peak>1e-32);rgbe=np.zeros((*peak.shape,4),np.uint8);rgbe[:,:,:3]=np.clip(data*scale[:,:,None],0,255).astype(np.uint8);rgbe[:,:,3]=np.where(peak>1e-32,exponent+128,0).astype(np.uint8)
 with filename.open('wb')as f:
  f.write(f'#?RADIANCE\nFORMAT=32-bit_rle_rgbe\n\n-Y {height} +X {width}\n'.encode())
  for row in rgbe:
   f.write(bytes([2,2,width>>8,width&255]))
   for channel in range(4):
    for x in range(0,width,128):block=row[x:x+128,channel].tobytes();f.write(bytes([len(block)]));f.write(block)
