 pixels=np.maximum(np.stack([np.asarray(Image.fromarray(rgb[:,:,k],mode='F').resize((512,256),Image.Resampling.LANCZOS))for k in range(3)],axis=2),0)if low else rgb;name='reflection-platform-enclosure'+('-low'if low else'')+'.hdr';q=a.out/name;write_hdr(q,pixels);loaded=bpy.data.images.load(str(q),check_existing=False);loaded.colorspace_settings.name='Non-Color';z=np.empty(len(loaded.pixels),np.float32);loaded.pixels.foreach_get(z);decoded=z.reshape(pixels.shape[0],pixels.shape[1],4)[:,:,:3];error=float(np.abs(decoded-pixels).mean()/max(float(pixels.mean()),1e-8));assert error<.02;packed=gzip.compress(q.read_bytes(),compresslevel=6,mtime=0);(a.out/(name+'.gz')).write_bytes(packed);outputs.append({'file':name+'.gz','bytes':len(packed),'decodedSha256':H(q.read_bytes()),'width':pixels.shape[1],'height':pixels.shape[0],'linearStats':stats(decoded),'roundtripRelativeMeanError':error})
